<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {assetUrl} from '@/services/api';
import type {Theme} from '@/domain/types';
import {visualVariables,themeForPage} from '@/domain/visual';
const props=defineProps<{theme:Theme;page:string;state:string}>();
const emit=defineEmits<{group:[value:string]}>();
const tab=ref('episodes'),episode=ref(1),password=ref(false);
watch(()=>props.page,()=>{tab.value='episodes';episode.value=1;});
const names:Record<string,string>={player:'播放器',detail:'影片详情',login:'登录 / 注册',downloads:'下载管理',feedback:'意见反馈',orders:'订单记录',recharge:'充值续费',dialog:'通用弹窗',empty:'空态与加载'};
const css=computed(()=>({backgroundImage:props.theme.pageDesign?.[props.page]?.backgroundImage?'url("'+assetUrl(props.theme.pageDesign[props.page].backgroundImage!)+'")':undefined,backgroundSize:'cover',backgroundPosition:'center',...visualVariables(themeForPage(props.theme,props.page)),'--bg':themeForPage(props.theme,props.page).colors.background,'--accent':props.theme.colors.accent,'--text':props.theme.colors.text,'--muted':props.theme.colors.muted}));
</script>
<template><view class="design-page" :style="css">
<view class="design-bar" @click="emit('group','appbar')"><text>‹</text><text>{{names[page]}}</text><text>···</text></view>
<view class="preview-ribbon">离线设计预览 · {{state==='loading'?'加载中':state==='error'?'失败':state==='empty'?'空内容':'正常'}}状态</view>
<template v-if="page==='player'||page==='detail'">
<view v-if="page==='player'" class="player-stage" @click="emit('group','player')"><view class="cinema-orbit"/><text class="watermark">{{theme.brand.name}}</text><view class="player-center"><text class="play-symbol">{{state==='loading'?'◌':state==='error'?'!':state==='empty'?'○':'▷'}}</text><text>{{state==='loading'?'正在加载 · 样式预览':state==='error'?'播放失败 · 错误态预览':state==='empty'?'暂无可播放内容':'暂停 · 控制层预览'}}</text></view><view class="player-bottom"><view class="timeline"><view class="buffer"/><view class="played"/></view><view class="player-controls"><text>▷</text><text>00:00 / --:--</text><text class="stretch"/><text>倍速</text><text>⛶</text></view></view></view>
<view v-if="page==='detail'" class="detail-cover" @click="emit('group','cards')"><view class="detail-poster">封面比例<br/>2 : 3</view><view><text class="overline">FILM DETAIL</text><text class="large-title">影片名称</text><text class="secondary">评分 · 年份 · 地区</text><text class="secondary">主演 / 导演信息</text></view></view><view class="design-content"><view class="design-card" @click="emit('group','cards')"><text class="overline">VIDEO DETAILS</text><text class="film-name">影片标题的位置</text><text class="secondary">年份 / 地区 / 分类 · 由真实内容填充</text><text class="description">简介区域展示主题的字号、颜色与间距。此处为排版示意，影片信息和播放地址由运营接口提供。</text><view class="quick-actions"><text>♡ 收藏</text><text>↓ 下载</text><text>↗ 分享</text></view></view>
<view class="tabs"><button :class="{active:tab==='episodes'}" @click="tab='episodes'">选集</button><button :class="{active:tab==='sources'}" @click="tab='sources'">播放线路</button><button :class="{active:tab==='related'}" @click="tab='related'">相关推荐</button></view><view v-if="state==='empty'" class="empty-design"><text>○</text><text>暂无{{tab==='episodes'?'选集':'内容'}}</text></view><view v-else-if="tab==='episodes'" class="episode-grid"><button v-for="n in 12" :key="n" :class="{chosen:episode===n}" @click="episode=n">{{String(n).padStart(2,'0')}}</button></view><view v-else-if="tab==='sources'" class="design-card"><text>线路列表样式</text><text class="secondary">示意线路 · 不发起播放请求</text></view><view v-else class="poster-grid"><view v-for="n in 3" :key="n" class="poster-example">海报比例</view></view></view>
</template>
<view v-else class="design-content">
<view v-if="state!=='normal'&&page!=='dialog'&&page!=='empty'" class="empty-design" @click="emit('group','empty')"><text>{{state==='loading'?'◌':state==='error'?'!':'○'}}</text><text>{{state==='loading'?'正在加载':state==='error'?'暂时无法加载':'暂无内容'}}</text><text class="secondary">{{state==='loading'?'正在预览等待反馈样式':state==='error'?'错误反馈与重试区域':'空内容时保留明确的说明'}}</text><view v-if="state==='error'" class="state-action">重试按钮区域</view></view><template v-else-if="page==='login'"><view class="account-logo">{{theme.brand.name.slice(0,1)}}</view><text class="large-title">欢迎回来</text><text class="secondary">账号表单 · 仅检验主题样式</text><view class="form-design" @click="emit('group','input')"><input placeholder="手机号 / 账号"/><view class="password-field"><input placeholder="输入密码" :password="!password"/><button @click="password=!password">{{password?'隐藏':'显示'}}</button></view><button class="accent-button" @click="emit('group','input')">登录按钮样式</button><view class="form-foot"><text>验证码登录</text><text>注册账号</text></view></view></template>
<template v-else-if="page==='recharge'"><view class="membership-card" @click="emit('group','cards')"><text class="overline">MEMBERSHIP</text><text class="large-title">会员卡片</text><text>权益说明与等级信息区域</text></view><view class="price-grid"><view v-for="name in ['月度','季度','年度']" :key="name" class="design-card"><text>{{name}}</text><text class="large-title">—</text><text class="secondary">运营定价</text></view></view><button class="accent-button">购买按钮样式</button></template>
<template v-else-if="page==='feedback'"><text class="large-title">告诉我们你的建议</text><view class="form-design" @click="emit('group','input')"><textarea placeholder="描述问题与建议（设计预览不提交）"/><input placeholder="联系方式（选填）"/><button class="accent-button">提交按钮样式</button></view></template>
<template v-else-if="page==='dialog'"><view class="dialog-backdrop"><view class="dialog-design" @click="emit('group','dialog')"><text class="large-title">{{state==='error'?'操作未完成':'提示弹窗'}}</text><text class="secondary">弹窗配色、间距和圆角预览。业务文案由运营中心提供。</text><view class="dialog-actions"><button>取消</button><button class="accent-button">确认</button></view></view></view></template>
<template v-else><view v-if="state==='normal'&&page!=='empty'" class="design-card" @click="emit('group','cards')"><text class="large-title">{{page==='downloads'?'下载任务卡片':'订单卡片'}}</text><text class="secondary">示意结构 · 没有真实任务或交易</text><view class="sample-line"/><text class="secondary">状态 / 时间 / 说明</text></view><view class="empty-design" @click="emit('group','empty')"><text>{{state==='loading'?'◌':state==='error'?'!':'○'}}</text><text>{{state==='loading'?'加载中':state==='error'?'暂时无法加载':page==='downloads'?'暂无下载任务':page==='orders'?'暂无订单':'暂无内容'}}</text><text class="secondary">{{state==='error'?'检查失败反馈的可读性':'检查空态图形与说明的层级'}}</text></view></template>
</view></view></template>
