dding:14px 18px;color:#071319;background:var(--accent);border-radius:var(--design-input-radius);border:0;font-size:14px;font-weight:600}.form-foot{display:flex;justify-content:space-between;font-size:12px;color:var(--muted)}.membership-card{display:flex;flex-direction:column;gap:16px;background:var(--design-cards-background);color:var(--design-cards-text);border-radius:var(--design-cards-radius);padding:var(--design-cards-gap);border:1px solid #d9bc7c44}.price-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.price-grid .design-card{padding:14px 10px;text-align:center}.dialog-backdrop{min-height:520px;background:#0005;display:flex;align-items:center;padding:10px}.dialog-design{background:var(--design-dialog-background);color:var(--design-dialog-text);border-radius:var(--design-dialog-radius);padding:24px;display:flex;flex-direction:column;gap:20px}.dialog-actions{display:flex;gap:14px}.dialog-actions button{flex:1;padding:12px;background:transparent;color:inherit;font-size:14px;border:1px solid #80808022;border-radius:var(--design-input-radius)}.dialog-actions .accent-button{background:var(--accent);color:#071319}.empty-design{min-height:260px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;font-size:14px;color:var(--design-empty-color)}.empty-design>text:first-child{font-size:var(--design-empty-size);line-height:1}.sample-line{height:4px;width:70%;border-radius:6px;background:var(--accent);opacity:.5}
